import React, { useState } from 'react';

export default function ManageSettings() {
  // 🏫 Institution Profile & Branding States
  const [instituteName, setInstituteName] = useState('AuraPen Institute of Education');
  const [contactEmail, setContactEmail] = useState('info@aurapen.lk');
  const [contactPhone, setContactPhone] = useState('+94 11 234 5678');
  const [address, setAddress] = useState('No 45, Colombo Road, Gampaha');

  // 🔒 Security Credentials States
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // 🌐 System Control Knobs (Toggles)
  const [allowStudentLogin, setAllowStudentLogin] = useState(true);
  const [allowTeacherLogin, setAllowTeacherLogin] = useState(true);
  const [maintenanceMode, setMaintenanceMode] = useState(false);
  const [sendSmsAlerts, setSendSmsAlerts] = useState(true);

  const handleSaveProfile = (e) => {
    e.preventDefault();
    alert("✅ Institution Profile updated successfully! All official PDF report templates will now use these dynamic branding nodes.");
  };

  const handleUpdatePassword = (e) => {
    e.preventDefault();
    if (!currentPassword || !newPassword || !confirmPassword) {
      alert("❌ Operation failed. All password allocation fields are mandatory!");
      return;
    }
    if (newPassword !== confirmPassword) {
      alert("❌ Password mismatch error! New Password and Confirm Password fields must be identical.");
      return;
    }
    alert("🔒 Security Update Successful! Master administrative credentials rotated safely.");
    setCurrentPassword('');
    setNewPassword('');
    setConfirmPassword('');
  };

  const handleSystemSync = () => {
    alert("🔄 Database Buffer Cleaned! System core configurations synced with MySQL Engine running on Port 8082.");
  };

  return (
    <div style={{ padding: '10px 0', fontFamily: 'sans-serif', color: '#334155' }}>
      
      <h2 style={{ margin: '0 0 25px 0', color: '#1e293b', fontSize: '22px', fontWeight: 'bold' }}>
        ⚙️ Master System Settings Desk
      </h2>

      <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 1fr', gap: '25px' }}>
        
        {/* LEFT COLUMN: GENERAL CONFIGURATIONS */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
          
          {/* Institute Profile Card */}
          <div style={styles.settingsCard}>
            <h3 style={styles.cardTitle}>🏫 Institution Metadata & Branding</h3>
            <p style={styles.cardSubtitle}>Configure official data fields extracted by the document layout generators.</p>
            
            <form onSubmit={handleSaveProfile} style={styles.formGrid}>
              <div style={styles.inputGroup}>
                <label style={styles.label}>Institute Registered Name</label>
                <input type="text" value={instituteName} onChange={(e) => setInstituteName(e.target.value)} style={styles.input} />
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Official Communication Email</label>
                <input type="email" value={contactEmail} onChange={(e) => setContactEmail(e.target.value)} style={styles.input} />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Helpdesk Hotline</label>
                  <input type="text" value={contactPhone} onChange={(e) => setContactPhone(e.target.value)} style={styles.input} />
                </div>
                <div style={styles.inputGroup}>
                  <label style={styles.label}>Physical Address Location</label>
                  <input type="text" value={address} onChange={(e) => setAddress(e.target.value)} style={styles.input} />
                </div>
              </div>

              <button type="submit" style={styles.saveBtn}>Save Institution Profile</button>
            </form>
          </div>

          {/* Core System Knobs */}
          <div style={styles.settingsCard}>
            <h3 style={styles.cardTitle}>🌐 Operational Environment Knobs</h3>
            <p style={styles.cardSubtitle}>Toggle network gateways and active student portal authorization blocks.</p>
            
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '15px' }}>
              
              <div style={styles.toggleRow}>
                <div>
                  <strong style={{ fontSize: '13.5px', color: '#1e293b' }}>Allow Student Portal Login Access</strong>
                  <p style={{ margin: '2px 0 0 0', fontSize: '12px', color: '#64748b' }}>If disabled, physically registered students cannot log in to check timetables.</p>
                </div>
                <input type="checkbox" checked={allowStudentLogin} onChange={(e) => setAllowStudentLogin(e.target.checked)} style={styles.checkbox} />
              </div>

              <div style={styles.toggleRow}>
                <div>
                  <strong style={{ fontSize: '13.5px', color: '#1e293b' }}>Allow Teacher Portal Database Modifications</strong>
                  <p style={{ margin: '2px 0 0 0', fontSize: '12px', color: '#64748b' }}>Controls whether faculty handles grading sheets online.</p>
                </div>
                <input type="checkbox" checked={allowTeacherLogin} onChange={(e) => setAllowTeacherLogin(e.target.checked)} style={styles.checkbox} />
              </div>

              <div style={styles.toggleRow}>
                <div>
                  <strong style={{ fontSize: '13.5px', color: '#1e293b' }}>Automated SMS Notification Alerts</strong>
                  <p style={{ margin: '2px 0 0 0', fontSize: '12px', color: '#64748b' }}>Dispatches automated warnings to parents when student scores hit Fail benchmarks.</p>
                </div>
                <input type="checkbox" checked={sendSmsAlerts} onChange={(e) => setSendSmsAlerts(e.target.checked)} style={styles.checkbox} />
              </div>

              <div style={styles.toggleRow}>
                <div>
                  <strong style={{ fontSize: '13.5px', color: '#b91c1c' }}>🚨 Server Maintenance Overhaul Mode</strong>
                  <p style={{ margin: '2px 0 0 0', fontSize: '12px', color: '#64748b' }}>Locks frontend routing modules down entirely for urgent internal testing schedules.</p>
                </div>
                <input type="checkbox" checked={maintenanceMode} onChange={(e) => setMaintenanceMode(e.target.checked)} style={styles.checkbox} />
              </div>

            </div>
          </div>

        </div>

        {/* RIGHT COLUMN: SECURITY & TECHNICAL ACTIONS */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
          
          {/* Authentication Card */}
          <div style={styles.settingsCard}>
            <h3 style={styles.cardTitle}>🔒 Administrative Key Security</h3>
            <p style={styles.cardSubtitle}>Safely rotate system root access keys to secure your SQL connections.</p>
            
            <form onSubmit={handleUpdatePassword} style={{ ...styles.formGrid, marginTop: '20px' }}>
              <div style={styles.inputGroup}>
                <label style={styles.label}>Active Root Password</label>
                <input type="password" placeholder="••••••••" value={currentPassword} onChange={(e) => setCurrentPassword(e.target.value)} style={styles.input} />
              </div>

              <div style={{ borderTop: '1px solid #f1f5f9', margin: '5px 0' }}></div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>New Encrypted Password String</label>
                <input type="password" placeholder="Minimum 6 security tags" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} style={styles.input} />
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Re-Type New Encryption</label>
                <input type="password" placeholder="Verify security tags" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} style={styles.input} />
              </div>

              <button type="submit" style={{ ...styles.saveBtn, backgroundColor: '#1e293b' }}>Rotate Security Keys</button>
            </form>
          </div>

          {/* Technical Diagnostics Utilities */}
          <div style={styles.settingsCard}>
            <h3 style={styles.cardTitle}>🛠️ Core System Utilities</h3>
            <p style={styles.cardSubtitle}>Trigger low-level system diagnostic queries manually.</p>
            
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '15px' }}>
              <button onClick={handleSystemSync} style={styles.utilBtn}>🔄 Flush App Buffers & Sync Cache</button>
              <button onClick={() => alert("📂 Local system logs backup dumped successfully into src/backups/log_dump.sql")} style={{...styles.utilBtn, backgroundColor: '#f8fafc', color: '#334155', border: '1px solid #cbd5e1'}}>📁 Backup System Log Tables</button>
            </div>
          </div>

        </div>

      </div>

    </div>
  );
}

const styles = {
  settingsCard: { backgroundColor: '#ffffff', padding: '25px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', display: 'flex', flexDirection: 'column' },
  cardTitle: { margin: '0 0 5px 0', fontSize: '15px', color: '#1e293b', fontWeight: 'bold' },
  cardSubtitle: { margin: 0, fontSize: '12px', color: '#64748b', lineHeight: '1.4' },
  formGrid: { display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '20px' },
  inputGroup: { display: 'flex', flexDirection: 'column', gap: '6px' },
  label: { fontSize: '12.5px', color: '#475569', fontWeight: '600' },
  input: { padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13px', backgroundColor: '#f8fafc', color: '#334155' },
  saveBtn: { padding: '10px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', marginTop: '5px' },
  toggleRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 15px', backgroundColor: '#f8fafc', borderRadius: '10px', border: '1px solid #f1f5f9' },
  checkbox: { width: '18px', height: '18px', cursor: 'pointer', accentColor: '#15803d' },
  utilBtn: { width: '100%', padding: '11px', backgroundColor: '#0284c7', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', textAlign: 'center' }
};
